namespace Gordic.Pok.WebClient {

    @Decorators.gcontent
    export class GPokPorovnaniRezervaceTab extends GContentBase {
      
        private grid: JQuery;  
        public ixp: string;

        onContentReady() {

            var that = this;

            this.title = 'Porovnání rezervace';           


            this.grid = $("<div>").appendTo(this.element).gautofit()
                .ggrid({
                    columnMode: "fit",
                    columns: this.createGridFormat()
                });


            that.NactiData();

        }

        private NactiData(): void {


            let that = this;

            that.beginOperation("Probíhá načtení rezervačních zápisů");

            that.isl.PokDoklad.listRezervacniZapisy(rq => {
                return {
                    ixp: that.ixp,

                }
            })
                .get().done(function (returnRezervacniZapisy) {

                    //rezervační zápisy

                    that.isl.PokDoklad.read({
                        ixp: that.ixp,
                        fragments: ["PokladniPolozky"]
                    })
                        .getData()
                        .done(function (dataDoklad) {

                            //pokladní doklad

                            let finishDataArray: Gordic.Pok.WebClient.GPokPorovnaniRezervaceDto[];
                            finishDataArray = [];

                            let y = 0;

                            if (dataDoklad.PokladniPolozky?.length != 0) {

                                dataDoklad.PokladniPolozky?.forEach(function (polozka) {
                                    let helpRow: GPokPorovnaniRezervaceDto;
                                    let helpRow2: GPokPorovnaniRezervaceDto;
                                    helpRow = {};
                                    helpRow2 = {};


                                    helpRow.popis = "Náhled";
                                    helpRow.radek = polozka.radek;

                                    that.call("RezervacniZapisy", { ixp: polozka.ixp, radek: polozka.radek })
                                        .done(function (row: GPokPorovnaniRezervaceDto) {

                                            y++;

                                            helpRow.uea = row.uea;
                                            helpRow.ueb = row.ueb;
                                            helpRow.uec = row.uec;
                                            helpRow.ued = row.ued;
                                            helpRow.uee = row.uee;
                                            helpRow.uef = row.uef;
                                            helpRow.ueg = row.ueg;
                                            helpRow.ueh = row.ueh;
                                            helpRow.uei = row.uei;
                                            helpRow.uej = row.uej;
                                            helpRow.te0 = row.te0;
                                            helpRow.te1 = row.te1;
                                            helpRow.te2 = row.te2;
                                            helpRow.te3 = row.te3;
                                            helpRow.te4 = row.te4;
                                            helpRow.nks = row.nks;
                                            helpRow.ucs = polozka.ucs;


                                            if (polozka.aktivita == 100)
                                                finishDataArray.push(helpRow);

                                            helpRow2.popis = "Skutečný";
                                            helpRow2.radek = polozka.radek;

                                            let rezervacniZaznam = returnRezervacniZapisy.filter(x => x.radek_ag == polozka.radek_upo_rez)[0];

                                            if (rezervacniZaznam) {

                                                helpRow2.uea = rezervacniZaznam.uea;
                                                helpRow2.ueb = rezervacniZaznam.ueb;
                                                helpRow2.uec = rezervacniZaznam.uec;
                                                helpRow2.ued = rezervacniZaznam.ued;
                                                helpRow2.uee = rezervacniZaznam.uee;
                                                helpRow2.uef = rezervacniZaznam.uef;
                                                helpRow2.ueg = rezervacniZaznam.ueg;
                                                helpRow2.ueh = rezervacniZaznam.ueh;
                                                helpRow2.uei = rezervacniZaznam.uei;
                                                helpRow2.uej = rezervacniZaznam.uej;
                                                helpRow2.te0 = rezervacniZaznam.te0;
                                                helpRow2.te1 = rezervacniZaznam.te1;
                                                helpRow2.te2 = rezervacniZaznam.te2;
                                                helpRow2.te3 = rezervacniZaznam.te3;
                                                helpRow2.te4 = rezervacniZaznam.te4;
                                                helpRow2.nks = rezervacniZaznam.nks;
                                                helpRow2.nks = rezervacniZaznam.nks;
                                                helpRow2.rok = rezervacniZaznam.rok;
                                                helpRow2.mesic = rezervacniZaznam.mesic;
                                                helpRow2.den = rezervacniZaznam.den;
                                                helpRow2.c0 = rezervacniZaznam.c0;
                                                helpRow2.c1 = rezervacniZaznam.c1;
                                                helpRow2.ucs = rezervacniZaznam.ucs;
                                                helpRow2.drd = rezervacniZaznam.drd?.toString();


                                                helpRow2.c = parseDecimal(new Decimal(rezervacniZaznam.c0!).minus(rezervacniZaznam.c1!));

                                            }


                                            if (polozka.aktivita == 100)
                                                finishDataArray.push(helpRow2);

                                            //vložení prázdného řádku jako oddělovače  
                                            if (polozka.aktivita == 100) {
                                                if (dataDoklad.PokladniPolozky?.length !== y) {
                                                    finishDataArray.push({});
                                                }
                                            }

                                            if (y == dataDoklad.PokladniPolozky?.length) {


                                                var view = new Gordic.Data.View(finishDataArray);
                                                that.grid.ggrid("setData", view);
                                                that.endOperation();

                                            }



                                        });  //end call




                                }) //end forecha

                            }//end id length
                            else {

                                that.endOperation();
                            }
                         

                        }) //end read
                }); //end listRezervacniZapisy


        }


        private createGridFormat(): Gordic.Data.GridFormat<Gordic.Fuc.Interface.GPohybDto> {
            var gridFormat = new Gordic.Data.GridFormat<Gordic.Fuc.Interface.GPohybDto>();

            gridFormat.addTextColumn({ name: "popis", caption: "Typ rezervačního zápisu" });        
            gridFormat.addNumberColumn({ name: "radek", caption: "#" });
            gridFormat.addTextColumn({ name: "drd", caption: "DRD" });
            gridFormat.addNumberColumn({ name: "rok", caption: "Rok" });
            gridFormat.addNumberColumn({ name: "mesic", caption: "Měsíc" });
            gridFormat.addNumberColumn({ name: "den", caption: "Den" });
            gridFormat.addTextColumn({ name: "nks", caption: "Nks" }); //UserProcess.Configuration.GetDatabaseShortcut("nks")
            gridFormat.addTextColumn({ name: "ucs", caption: "Ucs" }); // UserProcess.Configuration.GetDatabaseShortcut("ucs")
            gridFormat.addSortedEkoCfuSet(this, true)
            gridFormat.addCurrencyColumn({ name: "c", caption: "Příjem - výdej" });


            return gridFormat;

        }
    }
        }

    
